<?php
namespace App\Actions\Inspections;
use App\Enums\InspectionStatus as S; use App\Models\Inspection; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class TransitionInspection {public function handle(Inspection $i,int $actor,S $to,?string $reason=null):Inspection{return DB::transaction(function()use($i,$actor,$to,$reason){$i->refresh();$from=$i->status;$required=match($to){S::InProgress=>\App\Enums\InspectionResponsibility::Inspector,S::AwaitingReview=>\App\Enums\InspectionResponsibility::Reviewer,S::AwaitingApproval=>\App\Enums\InspectionResponsibility::Approver,S::Released=>\App\Enums\InspectionResponsibility::Releaser,default=>null};if($required!==null&&!$i->hasResponsibility($required))throw ValidationException::withMessages(['responsibles'=>'A responsabilidade técnica exigida não foi atribuída.']);$allowed=[[S::Planned,S::InProgress],[S::InProgress,S::AwaitingReview],[S::InCorrection,S::AwaitingReview],[S::AwaitingReview,S::InCorrection],[S::AwaitingApproval,S::InCorrection],[S::AwaitingReview,S::AwaitingApproval],[S::AwaitingApproval,S::Approved],[S::Approved,S::Released],[S::ReportGenerated,S::Released]];if($to===S::Canceled){if(in_array($from,[S::Released,S::Canceled],true))throw ValidationException::withMessages(['status'=>'A inspeção não pode ser cancelada.']);}elseif(!collect($allowed)->contains(fn($p)=>$p[0]===$from&&$p[1]===$to))throw ValidationException::withMessages(['status'=>'Transição inválida para o estado atual.']);$dates=match($to){S::InProgress=>['started_at'=>now()],S::AwaitingReview=>['field_completed_at'=>now()],S::AwaitingApproval=>['reviewed_at'=>now()],S::Approved=>['approved_at'=>now()],S::Released=>['released_at'=>now()],S::Canceled=>['canceled_at'=>now()],default=>[]};$i->update(['status'=>$to,'updated_by'=>$actor,...$dates]);$i->statusHistories()->create(['organization_id'=>$i->organization_id,'from_status'=>$from->value,'to_status'=>$to->value,'changed_by'=>$actor,'reason'=>$reason,'created_at'=>now()]);return $i->refresh();});}}
